            if doc_id in self.documents:
                return 409
            self.documents[doc_id] = body
            return 201

        def read(self, doc_id):
            if not self._is_valid_id(doc_id):
                return (400, None)
            if doc_id not in self.documents:
                return (404, None)
            return (200, self.documents[doc_id])

        def put(self, doc_id, body):
            if not self._is_valid_id(doc_id):
                return 400
            if doc_id not in self.documents:
                return 404
            if doc_id in self.archived:
                return 409
            self.documents[doc_id] = body
            return 200

        def archive(self, doc_id):
            if not self._is_valid_id(doc_id):
                return 400
            if doc_id not in self.documents:
                return 404
            if doc_id in self.archived:
