def test_create_document():
    store = make()
    assert store.create('doc1', 'body1') == 201
    assert store.create('doc1', 'body2') == 409
    assert store.create('invalid/doc', 'body') == 400
    assert store.create(123, 'body') == 400

def test_read_document():
    store = make()
    assert store.create('doc1', 'body1') == 201
    assert store.read('doc1') == (200, 'body1')
    assert store.read('missing') == (404, None)
    assert store.read('invalid/doc') == (400, None)
    assert store.read(123) == 400

def test_put_document():
    store = make()
    assert store.create('doc1', 'body1') == 201
    assert store.put('doc1', 'new_body') == 200
    assert store.read('doc1') == (200, 'new_body')
    assert store.put('missing', 'body') == 404
    assert store.archive('doc1') == 200
    assert store.put('doc1', 'another_body') == 409

def test_archive_document():
    store = make()
    assert store.create('doc1', 'body1') == 201
    assert store.archive('doc1') == 200
    assert store.read('doc1') == (200, 'body1')
    assert store.archive('doc1') == 409
    assert store.put('doc1', 'new_body') == 409
    assert store.read('doc1') == (200, 'body1')

def test_list_documents():
    store = make()
    assert store.create('doc1', 'body1') == 201
    assert store.create('doc2', 'body2') == 201
    assert store.archive('doc1') == 200
    assert store.list() == ['doc1', 'doc2']
    assert store.create('doc3', 'body3') == 201
    assert store.list() == ['doc1', 'doc2', 'doc3']
    assert store.create('doc..invalid', 'body') == 400
    assert store.create('doc/', 'body') == 400
    assert store.list() == ['doc1', 'doc2', 'doc3']

# Run tests
test_create_document()
test_read_document()
test_put_document()
test_archive_document()
test_list_documents()
