class DocumentStore:
    def __init__(self):
        self.documents = {}
        self.archived = set()
        self.valid_status_codes = {
            'archived_put': 409,
            'created': 201,
            'exists': 409,
            'invalid_id': 400,
            'missing': 404
        }

    def _is_valid_id(self, doc_id):
        if not isinstance(doc_id, str) or '/' in doc_id or '..' in doc_id:
            return False
        return True

    def create(self, doc_id, body):
        if not self._is_valid_id(doc_id):
            return self.valid_status_codes['invalid_id']
        if doc_id in self.documents:
            return self.valid_status_codes['exists']
        self.documents[doc_id] = body
        return self.valid_status_codes['created']

    def read(self, doc_id):
        if not self._is_valid_id(doc_id):
            return (self.valid_status_codes['invalid_id'], None)
        if doc_id not in self.documents:
            return (self.valid_status_codes['missing'], None)
        return (200, self.documents[doc_id])

    def put(self, doc_id, body):
        if not self._is_valid_id(doc_id):
            return self.valid_status_codes['invalid_id']
        if doc_id not in self.documents:
            return self.valid_status_codes['missing']
        if doc_id in self.archived:
            return self.valid_status_codes['archived_put']
        self.documents[doc_id] = body
        return 200

    def archive(self, doc_id):
        if not self._is_valid_id(doc_id):
            return self.valid_status_codes['invalid_id']
        if doc_id not in self.documents:
            return self.valid_status_codes['missing']
        self.archived.add(doc_id)
        return 200

    def list(self):
        all_ids = set(self.documents.keys()).union(self.archived)
        valid_ids = [doc_id for doc_id in all_ids if self._is_valid_id(doc_id)]
        return sorted(valid_ids)
